/* Exact segment/box occlusion for both text overlays and interactions. */
function segmentBoxHit(from,to,b,padding=0){let lo=0,hi=1;const min=[b.x-b.w/2-padding,b.y-padding,b.z-b.d/2-padding],max=[b.x+b.w/2+padding,b.y+b.h+padding,b.z+b.d/2+padding];for(let i=0;i<3;i++){const delta=to[i]-from[i];if(Math.abs(delta)<1e-9){if(from[i]<min[i]||from[i]>max[i])return null;}else{let a=(min[i]-from[i])/delta,c=(max[i]-from[i])/delta;if(a>c)[a,c]=[c,a];lo=Math.max(lo,a);hi=Math.min(hi,c);if(lo>hi)return null;}}return {lo,hi};}
let visibilityCache={version:-1,cells:new Map(),floors:[]};
function visibilityIndex(){if(visibilityCache.version===house.meshVersion)return visibilityCache;const cells=new Map(),floors=[];for(const b of house.solids){const x0=Math.floor((b.x-b.w/2)/4),x1=Math.floor((b.x+b.w/2)/4),z0=Math.floor((b.z-b.d/2)/4),z1=Math.floor((b.z+b.d/2)/4);for(let x=x0;x<=x1;x++)for(let z=z0;z<=z1;z++){const key=x+','+z;if(!cells.has(key))cells.set(key,[]);cells.get(key).push(b);}}
 // Architectural slabs are rendered geometry, not walk-blocking furniture.
 for(const f of house.faces){const y=f.v[0][1];if(!f.v.every(p=>Math.abs(p[1]-y)<.001)||y<2.7)continue;const xs=f.v.map(p=>p[0]),zs=f.v.map(p=>p[2]),w=Math.max(...xs)-Math.min(...xs),d=Math.max(...zs)-Math.min(...zs);if(w>.6&&d>.6)floors.push({x:(Math.max(...xs)+Math.min(...xs))/2,z:(Math.max(...zs)+Math.min(...zs))/2,w,d,y:y-.004,h:.008});}
 visibilityCache={version:house.meshVersion,cells,floors};return visibilityCache;}
function clearWorldSegment(from,to){if(!from.concat(to).every(Number.isFinite))return false;const index=visibilityIndex(),candidates=new Set(index.floors),steps=Math.max(1,Math.ceil(Math.hypot(to[0]-from[0],to[2]-from[2])/2));for(let i=0;i<=steps;i++){const t=i/steps,key=Math.floor((from[0]+(to[0]-from[0])*t)/4)+','+Math.floor((from[2]+(to[2]-from[2])*t)/4);const [cx,cz]=key.split(',').map(Number);for(let ox=-1;ox<=1;ox++)for(let oz=-1;oz<=1;oz++)for(const b of index.cells.get((cx+ox)+','+(cz+oz))||[])candidates.add(b);}
 const length=Math.hypot(...to.map((v,i)=>v-from[i]));for(const b of candidates){const hit=segmentBoxHit(from,to,b);if(hit&&hit.hi>.001&&hit.lo<1-.035/Math.max(.035,length)){// Permit only a thin support at the target endpoint, never intervening walls.
 if(hit.lo>0&&length*(1-hit.lo)<.035)continue;return false;}}return true;}
visibleTo=function(t){if(!t?.p||!clearWorldSegment([house.x,1.55+(house.jumpHeight||0)+(house.walkBob||0),house.z],t.p))return false;if(typeof playerCamera!=='undefined'&&playerCamera.third&&advancedEngine?.camera){const c=advancedEngine.camera.position;return clearWorldSegment([c.x,c.y,-c.z],t.p);}return true;};
const maintenanceDecal=drawDecal;drawDecal=function(img,quad){const camera=typeof playerCamera!=='undefined'&&playerCamera.third&&advancedEngine?.camera?advancedEngine.camera.position:null,from=camera?[camera.x,camera.y,-camera.z]:[house.x,1.55+(house.jumpHeight||0)+(house.walkBob||0),house.z];const center=quad[0].map((_,i)=>quad.reduce((v,p)=>v+p[i]/quad.length,0));if(!clearWorldSegment(from,center)||quad.some(p=>!clearWorldSegment(from,p.map((v,i)=>v*.96+center[i]*.04))))return;return maintenanceDecal(img,quad);};
// Check intermediate horizontal positions so fast movement cannot tunnel through thin frames.
const maintenanceWalk=canWalk;canWalk=function(x,z){const distance=Math.hypot(x-house.x,z-house.z);if(distance>.75||distance<.035||window.spareAdmin?.status?.().tools?.fly)return maintenanceWalk(x,z);const steps=Math.ceil(distance/.045);for(let i=1;i<=steps;i++)if(!maintenanceWalk(house.x+(x-house.x)*i/steps,house.z+(z-house.z)*i/steps))return false;return true;};
// Bounded candidate distances make narrow rooms useful without invalid placements.
anomalyAnchor=function(distance=3.3,radius=.32){const floor=supportAt(house.x,house.z);for(const scale of [1,.75,.5])for(const turn of [.5,-.5,0,1.1,-1.1,Math.PI]){const a=house.a+turn,x=house.x+Math.sin(a)*distance*scale,z=house.z+Math.cos(a)*distance*scale;if(Math.hypot(x-house.x,z-house.z)<1.15)continue;if([[0,0],[radius,0],[-radius,0],[0,radius],[0,-radius]].every(([dx,dz])=>canWalk(x+dx,z+dz)&&Math.abs(supportAt(x+dx,z+dz)-floor)<.12)&&visibleTo({p:[x,floor+1.2,z]}))return [x,floor,z];}return null;};
